actions.script:
let project = null
if (ec.context.get('inProjectDetail')) {
    const projectId = ec.context.get('projectTabId')
    project = projectId ? ec.service.sync().name('ironstone.projects.ProjectServices.get#ProjectDocs').parameters({workEffortId: projectId}).call()?.docs || null : null
    ec.message.clearErrors()
    if (project == null) { ec.web.sendJsonResponse({spaceList: [], recentList: [], reviewCount: 0, me: {}, project: {notAvailable: true, linkedList: [], repositoryOptions: []}}); return }
}
// in Customer Service (CustomerService/Knowledge's always-actions set inCustomerService) the spaces are its knowledge
// sources' (ironstone.customerservice.KnowledgeServices.get#KnowledgeContext, answered as service), with the case worked on
let service = null
if (ec.context.get('inCustomerService')) {
    service = ec.service.sync().name('ironstone.customerservice.KnowledgeServices.get#KnowledgeContext').parameters({appRoot: 'CustomerService',
        requestId: ec.context.get('requestId') || null}).call()?.knowledgeContext || null
    ec.message.clearErrors()
    if (service == null) { ec.web.sendJsonResponse({spaceList: [], recentList: [], reviewCount: 0, me: {}, service: {spaceIds: []}}); return }
}
const out = ec.service.sync().name('ironstone.commons.KnowledgeServices.get#KnowledgeSetup').parameter('wikiSpaceId', project ? project.wikiSpaceId : (wikiSpaceId || null)).call()
if (ec.message.hasError()) { ec.web.sendJsonResponse({}); return }
const spaceList = project ? Array.from(out.spaceList || []).filter((space) => space.wikiSpaceId === project.wikiSpaceId)
    : service ? Array.from(out.spaceList || []).filter((space) => Array.from(service.spaceIds || []).includes(space.wikiSpaceId)) : out.spaceList
const defaultSpaceId = project ? (spaceList.length ? project.wikiSpaceId : null) : service
    ? (spaceList.some((space) => space.wikiSpaceId === out.defaultWikiSpaceId) ? out.defaultWikiSpaceId : (spaceList[0]?.wikiSpaceId || null)) : out.defaultWikiSpaceId
ec.web.sendJsonResponse({spaceList: spaceList, defaultWikiSpaceId: defaultSpaceId,
    recentList: project || service ? [] : out.recentList, reviewCount: out.reviewCount, me: out.me, failedParts: out.failedParts, project: project,
    service: service})

const projectId = ec.context.get('projectTabId')
if (!projectId) ec.message.addError(ec.l10n.localize('Project not available'))
const out = projectId ? ec.service.sync().name('ironstone.projects.ProjectServices.setup#ProjectDocs').parameters({workEffortId: projectId, storage: storage || 'db',
    repositoryId: repositoryId || null}).call() || {} : {}
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {wikiSpaceId: out.wikiSpaceId, messageInfos: [{type: 'success', message: out.message}]})

const projectId = ec.context.get('projectTabId')
if (!projectId) ec.message.addError(ec.l10n.localize('Project not available'))
const out = projectId ? ec.service.sync().name('ironstone.projects.ProjectServices.link#ProjectDocsPage').parameters({workEffortId: projectId, wikiPageId: wikiPageId || '',
    unlink: String(unlink) === 'true'}).call() || {} : {}
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {messageInfos: [{type: 'success', message: out.message}]})

const projectId = ec.context.get('projectTabId')
const own = projectId ? ec.entity.find('mantle.work.effort.WorkEffortSetting').condition({workEffortId: projectId, settingTypeEnumId: 'WstDocsWikiSpace'}).one()?.settingValue : null
const out = projectId && term ? ec.service.sync().name('ironstone.commons.KnowledgeServices.search#Pages').parameters({text: term, scope: 'knowledge', limit: 15}).call() || {} : {}
ec.message.clearErrors()
ec.web.sendJsonResponse(Array.from(out.pageList || []).filter((hit) => hit.wikiPageId && hit.wikiSpaceId !== own)
        .map((hit) => ({value: hit.wikiPageId, label: (hit.title || hit.pagePath || hit.wikiSpaceId) + ' · ' + (hit.spaceDescription || hit.wikiSpaceId)})))

if (!ec.context.get('inCustomerService')) ec.message.addError(ec.l10n.localize('Not available here'))
if (!ec.message.hasError()) ec.service.sync().name('ironstone.customerservice.AccessServices.check#Record').parameters({appRoot: 'CustomerService',
    recordType: 'case', recordId: requestId || '', capability: 'caseEdit'}).call()
if (!ec.message.hasError()) ec.service.sync().name('mantle.request.RequestServices.link#RequestRecord').parameters({requestId: requestId,
    recordEntityName: 'moqui.resource.wiki.WikiPage', recordId: wikiPageId || ''}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {messageInfos: [{type: 'success', message: ec.resource.expand('Linked to case ${id}', '', {id: requestId})}]})

if (!ec.context.get('inCustomerService')) ec.message.addError(ec.l10n.localize('Not available here'))
const out = ec.message.hasError() ? {} : ec.service.sync().name('ironstone.customerservice.KnowledgeServices.prepare#ArticleSend').parameters({appRoot: 'CustomerService',
    requestId: requestId || '', wikiPageId: wikiPageId || ''}).call() || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {composeUrl: out.send?.composeUrl || null})

if (!ec.context.get('inCustomerService')) ec.message.addError(ec.l10n.localize('Not available here'))
if (!ec.message.hasError() && requestId) ec.service.sync().name('ironstone.customerservice.AccessServices.check#Record').parameters({appRoot: 'CustomerService',
    recordType: 'case', recordId: requestId, capability: 'caseEdit'}).call()
if (!ec.message.hasError()) ec.service.sync().name('mantle.request.KnowledgeServices.suggest#ArticleEdit').parameters({wikiPageId: wikiPageId || '',
    note: note || null, requestId: requestId || null}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {messageInfos: [{type: 'success', message: ec.l10n.localize('Your suggestion is with the review team')}]})

const out = ec.service.sync().name('ironstone.commons.KnowledgeServices.get#PageChildren').parameters({wikiSpaceId: wikiSpaceId || '',
    pagePath: pagePath || ''}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {childList: out.childList})

const out = ec.service.sync().name('ironstone.commons.KnowledgeServices.get#PageView').parameters({wikiPageId: wikiPageId || null,
    wikiSpaceId: wikiSpaceId || null, pagePath: pagePath || '', versionName: versionName || null}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {page: out.page, failedParts: out.failedParts})

const out = ec.service.sync().name('ironstone.commons.KnowledgeServices.search#Pages').parameters({text: text || '', wikiSpaceId: wikiSpaceId || null,
    scope: 'knowledge'}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {pageList: out.pageList, usedIndex: out.usedIndex})

const out = ec.service.sync().name('ironstone.commons.KnowledgeServices.get#SpacePageOptions').parameters({wikiSpaceId: wikiSpaceId || '',
    excludePagePath: excludePagePath || null}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {optionList: out.optionList, canUpdate: out.canUpdate})

const out = ec.service.sync().name('ironstone.commons.KnowledgeServices.get#Attachment').parameters({wikiPageId: wikiPageId || '',
    filename: filename || ''}).call()
if (ec.message.hasError()) ec.web.sendJsonResponse({})
else ec.web.sendResourceResponse(out.location, String(inline) === 'true' && out.inlineAllowed)

const out = ec.service.sync().name('ironstone.commons.KnowledgeServices.rename#Page').parameters({wikiPageId: wikiPageId || '', pageName: pageName || ''}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {wikiSpaceId: out.wikiSpaceId, pagePath: out.pagePath,
    messageInfos: [{type: 'success', message: ec.l10n.localize('Renamed')}]})

const out = ec.service.sync().name('ironstone.commons.KnowledgeServices.duplicate#Page').parameters({wikiPageId: wikiPageId || '',
    toWikiSpaceId: toWikiSpaceId || null, toParentPath: toParentPath || '', toPageName: toPageName || '',
    withChildren: String(withChildren) === 'true' || withChildren === 'Y'}).call()
if (ec.message.hasError()) { ec.web.sendJsonResponse({}); return }
const failed = Array.from(out.failedPaths || [])
const infos = [{type: 'success', message: out.pageCount > 1 ? ec.resource.expand('Copied, with ${count} pages under it', '', {count: out.pageCount - 1})
    : ec.l10n.localize('Copied')}]
if (failed.length) infos.push({type: 'warning', message: ec.resource.expand('Not copied: ${list}', '', {list: failed.join(', ')})})
ec.web.sendJsonResponse({wikiPageId: out.wikiPageId, wikiSpaceId: out.wikiSpaceId, pagePath: out.pagePath, pageCount: out.pageCount,
    failedPaths: failed, messageInfos: infos})

const out = ec.service.sync().name('ironstone.commons.KnowledgeServices.drop#Page').parameters({wikiPageId: wikiPageId || '',
    targetPagePath: targetPagePath || '', position: position || 'inside'}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {wikiSpaceId: out.wikiSpaceId, pagePath: out.pagePath, oldPagePath: out.oldPagePath})

const out = ec.service.sync().name('ironstone.commons.KnowledgeServices.delete#Page').parameter('wikiPageId', wikiPageId || '').call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {wikiSpaceId: out.wikiSpaceId, parentPath: out.parentPath,
    messageInfos: [{type: 'success', message: ec.l10n.localize('Page deleted')}]})

const out = ec.service.sync().name('ironstone.commons.KnowledgeServices.cancel#Review').parameters({wikiPageReviewId: wikiPageReviewId || '',
    note: note || null}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {statusId: out.statusId, messageInfos: [{type: 'success', message: ec.l10n.localize('Review request cancelled')}]})

const out = ec.service.sync().name('ironstone.commons.KnowledgeServices.set#PagePinned').parameters({wikiPageId: wikiPageId || '',
    pinned: String(pinned) === 'true'}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {pinned: out.pinned})

// the drop-down's value is entity|id
const value = String(record || '')
const bar = value.indexOf('|')
const entityName = bar > 0 ? value.substring(0, bar) : ''
const id = bar > 0 ? value.substring(bar + 1) : ''
ec.service.sync().name('ironstone.commons.KnowledgeServices.link#PageRecord').parameters({wikiPageId: wikiPageId || '',
    recordEntityName: recordEntityName || entityName || '', recordId: recordId || id || ''}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {messageInfos: [{type: 'success', message: ec.l10n.localize('Linked')}]})

render-mode.text:
${JSON.stringify([{t: "dynamicContainer", id: "KnowledgeTui", url: sri.buildUrl("../KnowledgeTui")
                .addParameters({wikiSpaceId: wikiSpaceId || null, pagePath: pagePath || null, wikiPageId: wikiPageId || null,
                    workEffortId: ec.context.get("inProjectDetail") ? (ec.context.get("projectTabId") || workEffortId || null) : null}).getUrlWithParams()}])}
